cd "/Users/lesurmatthis/dev/projet perso/collega/collega_app" && python3 - <<'EOF'
p='lib/core/ui/components/cg_segmented.dart'
s=open(p).read()
old="""          Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              for (final value in values)
                Expanded(child: _segment(context, value)),
            ],
          ),"""
new="""          // Hauteur commune : si un libellé passe sur deux lignes, toutes les
          // cellules (et la pastille) prennent sa hauteur.
          IntrinsicHeight(
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                for (final value in values) Expanded(child: _segment(context, value)),
              ],
            ),
          ),"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF completed
